cat >> apps/web/modules/integrations/webhooks/lib/webhook.test.ts <<'EOF'

describe("getWebhookCopyName", () => {
  test("prefixes the original name", () => {
    expect(getWebhookCopyName({ name: "Slack alerts", url: "https://example.com/hook" })).toBe(
      "Copy of Slack alerts"
    );
  });

  test.each([null, "", "   "])("falls back to the URL when the name is %j", (name) => {
    expect(getWebhookCopyName({ name, url: "https://example.com/hook" })).toBe(
      "Copy of https://example.com/hook"
    );
  });
});

describe("duplicateWebhook", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.mocked(validateWebhookUrl).mockResolvedValue(undefined);
    vi.mocked(isDiscordWebhook).mockReturnValue(false);
    vi.mocked(generateWebhookSecret).mockReturnValue("new-secret");
  });

  test("copies URL, triggers and surveys into the same workspace with a new secret", async () => {
    vi.mocked(prisma.webhook.create).mockResolvedValue({ id: "copy" } as never);

    await duplicateWebhook({
      name: "Slack alerts",
      url: "https://example.com/hook",
      triggers: ["responseCreated", "responseFinished"],
      surveyIds: ["survey_1", "survey_2"],
      workspaceId: "workspace_1",
    });

    expect(prisma.webhook.create).toHaveBeenCalledWith({
      data: {
        name: "Copy of Slack alerts",
        url: "https://example.com/hook",
        source: "user",
        triggers: ["responseCreated", "responseFinished"],
        surveyIds: ["survey_1", "survey_2"],
        secret: "new-secret",
        workspace: { connect: { id: "workspace_1" } },
      },
    });
  });

  test("re-validates the URL, so a copy cannot outlive a tightened URL policy", async () => {
    vi.mocked(validateWebhookUrl).mockRejectedValue(new InvalidInputError("blocked"));

    await expect(
      duplicateWebhook({
        name: null,
        url: "http://10.0.0.1/hook",
        triggers: ["responseCreated"],
        surveyIds: [],
        workspaceId: "workspace_1",
      })
    ).rejects.toThrow(InvalidInputError);
    expect(prisma.webhook.create).not.toHaveBeenCalled();
  });
});
